-- (ㄱ)
SELECT CHAR_NM AS "이름", LV FROM CHARS ORDER BY "이름";

-- (ㄴ)
SELECT CHAR_NM, LV * 2 AS LV2 FROM CHARS WHERE LV2 > 100;

-- (ㄷ)
SELECT DISTINCT SERVER_ID FROM CHARS ORDER BY LV;

-- (ㄹ)
SELECT C.*, LV FROM CHARS C;

-- (가)
SELECT COUNT(*) FROM ITEM WHERE ITEM_NM LIKE 'HP_%';

-- (나)
SELECT COUNT(*) FROM ITEM WHERE ITEM_NM LIKE 'HP\_%' ESCAPE '\';

-- (다)
SELECT COUNT(*) FROM ITEM WHERE ITEM_NM LIKE '%\%%' ESCAPE '\';

SELECT C.CHAR_ID, G.GRADE
FROM   CHARS C, LV_GRADE G
WHERE  C.LV BETWEEN G.MIN_LV AND G.MAX_LV;

-- (가)
SELECT COUNT(*) FROM ACCT A FULL OUTER JOIN PAY P ON A.ACCT_ID = P.ACCT_ID;

-- (나)
SELECT COUNT(*) FROM ACCT A LEFT OUTER JOIN PAY P
       ON A.ACCT_ID = P.ACCT_ID AND P.AMT > 10000;

-- (다)
SELECT COUNT(*) FROM ACCT A RIGHT OUTER JOIN PAY P ON A.ACCT_ID = P.ACCT_ID
WHERE  A.ACCT_ID IS NULL;

-- (가)
SELECT COUNT(*) FROM CHARS WHERE LV > ALL (SELECT LV FROM CHARS WHERE SERVER_ID = 'S9');
-- (나)
SELECT COUNT(*) FROM CHARS WHERE LV > ANY (SELECT LV FROM CHARS WHERE SERVER_ID = 'S9');
-- (다)
SELECT COUNT(*) FROM CHARS WHERE LV > ALL (SELECT EVT_LV FROM EVT);
-- (라)
SELECT COUNT(*) FROM CHARS WHERE LV > ANY (SELECT EVT_LV FROM EVT);

-- (가)
SELECT COUNT(*) FROM (SELECT ACCT_ID FROM EVT1 UNION     SELECT ACCT_ID FROM EVT2);
-- (나)
SELECT COUNT(*) FROM (SELECT ACCT_ID FROM EVT1 MINUS     SELECT ACCT_ID FROM EVT2);
-- (다)
SELECT COUNT(*) FROM (SELECT ACCT_ID FROM EVT1 INTERSECT SELECT ACCT_ID FROM EVT2);
-- (라)
SELECT COUNT(*) FROM (SELECT ACCT_ID FROM EVT1 UNION ALL SELECT ACCT_ID FROM EVT2);

-- (가)
SELECT SERVER_ID, PAY_TYPE, SUM(AMT) FROM PAY GROUP BY ROLLUP(SERVER_ID, PAY_TYPE);
-- (나)
SELECT SERVER_ID, PAY_TYPE, SUM(AMT) FROM PAY GROUP BY CUBE(SERVER_ID, PAY_TYPE);
-- (다)
SELECT SERVER_ID, PAY_TYPE, SUM(AMT) FROM PAY GROUP BY GROUPING SETS(SERVER_ID, PAY_TYPE, ());
-- (라)
SELECT SERVER_ID, PAY_TYPE, SUM(AMT) FROM PAY GROUP BY SERVER_ID, ROLLUP(PAY_TYPE);

-- (가)
SELECT PAY_NO, AMT FROM PAY WHERE ROWNUM <= 3 ORDER BY AMT DESC;

-- (나)
SELECT * FROM (SELECT PAY_NO, AMT FROM PAY ORDER BY AMT DESC)
WHERE  ROWNUM <= 3;

-- (다)
SELECT PAY_NO, AMT FROM PAY ORDER BY AMT DESC FETCH FIRST 3 ROWS WITH TIES;

-- (라)
SELECT PAY_NO, AMT FROM PAY WHERE ROWNUM = 2;

UPDATE CHARS SET GOLD = GOLD - 100 WHERE CHAR_ID = 'C1';
SAVEPOINT SP1;
UPDATE CHARS SET GOLD = GOLD - 200 WHERE CHAR_ID = 'C1';
SAVEPOINT SP2;
UPDATE CHARS SET GOLD = GOLD - 300 WHERE CHAR_ID = 'C1';
ROLLBACK TO SP1;
UPDATE CHARS SET GOLD = GOLD + 50  WHERE CHAR_ID = 'C1';
CREATE TABLE TMP_X (A NUMBER);
UPDATE CHARS SET GOLD = GOLD * 2   WHERE CHAR_ID = 'C1';
ROLLBACK;
SELECT GOLD FROM CHARS WHERE CHAR_ID = 'C1';

CREATE TABLE GUILD (
  GUILD_ID   VARCHAR2(10) PRIMARY KEY,
  GUILD_NM   VARCHAR2(50) NOT NULL
);

CREATE TABLE CHARS (
  CHAR_ID    VARCHAR2(10) PRIMARY KEY,
  CHAR_NM    VARCHAR2(30) NOT NULL,
  GUILD_ID   VARCHAR2(10),
  CONSTRAINT FK_CHARS_GUILD FOREIGN KEY (GUILD_ID)
             REFERENCES GUILD (GUILD_ID) ON DELETE SET NULL
);

